invalidate() {
  if (!this._inBatch) {
    threadTree.reset();
    if (threadPane) {
      threadPane.isFirstScroll = true;
      threadPane.scrollDetected = false;
      threadPane.scrollToLatestRowIfNoSelection();
    }
  }
},
invalidateRange(startIndex, endIndex) {
  if (!this._inBatch) {
    threadTree.invalidateRange(startIndex, endIndex);
  }
},
